-- ============================================================
--  Telco Customer Churn Database
--  Normalized to BCNF (Boyce-Codd Normal Form / 3.5NF)
--  Target RDBMS : Microsoft SQL Server
--  Generated    : 2026-05-06
-- ============================================================

USE master;
GO

IF DB_ID('TelcoChurnDB') IS NOT NULL
BEGIN
    ALTER DATABASE TelcoChurnDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE TelcoChurnDB;
END
GO

CREATE DATABASE TelcoChurnDB
    COLLATE Latin1_General_CI_AS;
GO

USE TelcoChurnDB;
GO

-- ============================================================
--  SECTION 1 – DIMENSION / LOOKUP TABLES
-- ============================================================

-- ------------------------------------------------------------
--  dim_Gender
-- ------------------------------------------------------------
CREATE TABLE dim_Gender (
    GenderID    TINYINT      NOT NULL IDENTITY(1,1),
    GenderName  NVARCHAR(10) NOT NULL,
    CONSTRAINT PK_dim_Gender      PRIMARY KEY (GenderID),
    CONSTRAINT UQ_dim_Gender_Name UNIQUE      (GenderName)
);
GO

-- ------------------------------------------------------------
--  dim_InternetServiceType
-- ------------------------------------------------------------
CREATE TABLE dim_InternetServiceType (
    InternetServiceTypeID   TINYINT      NOT NULL IDENTITY(1,1),
    ServiceTypeName         NVARCHAR(20) NOT NULL,
    CONSTRAINT PK_dim_InternetServiceType      PRIMARY KEY (InternetServiceTypeID),
    CONSTRAINT UQ_dim_InternetServiceType_Name UNIQUE      (ServiceTypeName)
);
GO

-- ------------------------------------------------------------
--  dim_ContractType
-- ------------------------------------------------------------
CREATE TABLE dim_ContractType (
    ContractTypeID    TINYINT      NOT NULL IDENTITY(1,1),
    ContractTypeName  NVARCHAR(30) NOT NULL,
    CONSTRAINT PK_dim_ContractType      PRIMARY KEY (ContractTypeID),
    CONSTRAINT UQ_dim_ContractType_Name UNIQUE      (ContractTypeName)
);
GO

-- ------------------------------------------------------------
--  dim_PaymentMethod
-- ------------------------------------------------------------
CREATE TABLE dim_PaymentMethod (
    PaymentMethodID    TINYINT      NOT NULL IDENTITY(1,1),
    MethodName         NVARCHAR(40) NOT NULL,
    CONSTRAINT PK_dim_PaymentMethod      PRIMARY KEY (PaymentMethodID),
    CONSTRAINT UQ_dim_PaymentMethod_Name UNIQUE      (MethodName)
);
GO

-- ============================================================
--  SECTION 2 – CORE ENTITY TABLES
-- ============================================================

-- ------------------------------------------------------------
--  Customer  (demographics only)
-- ------------------------------------------------------------
CREATE TABLE Customer (
    CustomerID       NVARCHAR(10) NOT NULL,
    GenderID         TINYINT      NOT NULL,
    IsSeniorCitizen  BIT          NOT NULL,
    HasPartner       BIT          NOT NULL,
    HasDependents    BIT          NOT NULL,
    Tenure           SMALLINT     NOT NULL  CHECK (Tenure >= 0),
    CONSTRAINT PK_Customer         PRIMARY KEY (CustomerID),
    CONSTRAINT FK_Customer_Gender  FOREIGN KEY (GenderID)
        REFERENCES dim_Gender (GenderID)
);
GO

-- ------------------------------------------------------------
--  CustomerPhoneService
--  HasMultipleLines is NULL when HasPhoneService = 0
--  (eliminates "No phone service" pseudo-value → removes
--   transitive dependency PhoneService → MultipleLines)
-- ------------------------------------------------------------
CREATE TABLE CustomerPhoneService (
    CustomerID       NVARCHAR(10) NOT NULL,
    HasPhoneService  BIT          NOT NULL,
    HasMultipleLines BIT          NULL,
    CONSTRAINT PK_CustomerPhoneService    PRIMARY KEY (CustomerID),
    CONSTRAINT FK_CPS_Customer            FOREIGN KEY (CustomerID)
        REFERENCES Customer (CustomerID),
    CONSTRAINT CHK_MultipleLines CHECK (
        HasPhoneService = 1 OR HasMultipleLines IS NULL
    )
);
GO

-- ------------------------------------------------------------
--  CustomerInternetService
--  InternetServiceTypeID = NULL when no internet service
--  All add-on flags NULL when no internet (removes
--  transitive dependency InternetService → add-ons)
-- ------------------------------------------------------------
CREATE TABLE CustomerInternetService (
    CustomerID              NVARCHAR(10) NOT NULL,
    InternetServiceTypeID   TINYINT      NULL,
    HasOnlineSecurity       BIT          NULL,
    HasOnlineBackup         BIT          NULL,
    HasDeviceProtection     BIT          NULL,
    HasTechSupport          BIT          NULL,
    HasStreamingTV          BIT          NULL,
    HasStreamingMovies      BIT          NULL,
    CONSTRAINT PK_CustomerInternetService     PRIMARY KEY (CustomerID),
    CONSTRAINT FK_CIS_Customer                FOREIGN KEY (CustomerID)
        REFERENCES Customer (CustomerID),
    CONSTRAINT FK_CIS_InternetServiceType     FOREIGN KEY (InternetServiceTypeID)
        REFERENCES dim_InternetServiceType (InternetServiceTypeID),
    CONSTRAINT CHK_AddOnsRequireInternet CHECK (
        InternetServiceTypeID IS NOT NULL OR (
            HasOnlineSecurity   IS NULL AND
            HasOnlineBackup     IS NULL AND
            HasDeviceProtection IS NULL AND
            HasTechSupport      IS NULL AND
            HasStreamingTV      IS NULL AND
            HasStreamingMovies  IS NULL
        )
    )
);
GO

-- ------------------------------------------------------------
--  CustomerBilling
-- ------------------------------------------------------------
CREATE TABLE CustomerBilling (
    CustomerID        NVARCHAR(10)   NOT NULL,
    ContractTypeID    TINYINT        NOT NULL,
    IsPaperless       BIT            NOT NULL,
    PaymentMethodID   TINYINT        NOT NULL,
    MonthlyCharges    DECIMAL(8, 2)  NOT NULL  CHECK (MonthlyCharges >= 0),
    TotalCharges      DECIMAL(10, 2) NULL       CHECK (TotalCharges  >= 0),
    CONSTRAINT PK_CustomerBilling           PRIMARY KEY (CustomerID),
    CONSTRAINT FK_CB_Customer               FOREIGN KEY (CustomerID)
        REFERENCES Customer (CustomerID),
    CONSTRAINT FK_CB_ContractType           FOREIGN KEY (ContractTypeID)
        REFERENCES dim_ContractType (ContractTypeID),
    CONSTRAINT FK_CB_PaymentMethod          FOREIGN KEY (PaymentMethodID)
        REFERENCES dim_PaymentMethod (PaymentMethodID)
);
GO

-- ------------------------------------------------------------
--  CustomerChurn  (analytic outcome – separated so it can
--  be updated independently without touching core records)
-- ------------------------------------------------------------
CREATE TABLE CustomerChurn (
    CustomerID  NVARCHAR(10) NOT NULL,
    HasChurned  BIT          NOT NULL,
    CONSTRAINT PK_CustomerChurn    PRIMARY KEY (CustomerID),
    CONSTRAINT FK_CC_Customer      FOREIGN KEY (CustomerID)
        REFERENCES Customer (CustomerID)
);
GO

-- ============================================================
--  SECTION 3 – INDEXES
-- ============================================================
CREATE INDEX IX_Customer_Gender         ON Customer               (GenderID);
CREATE INDEX IX_CIS_InternetServiceType ON CustomerInternetService (InternetServiceTypeID);
CREATE INDEX IX_CB_ContractType         ON CustomerBilling         (ContractTypeID);
CREATE INDEX IX_CB_PaymentMethod        ON CustomerBilling         (PaymentMethodID);
CREATE INDEX IX_CustomerChurn_HasChurned ON CustomerChurn          (HasChurned);
GO


-- ============================================================
--  SECTION 4 – LOOKUP DATA
-- ============================================================

SET IDENTITY_INSERT dim_Gender ON;
SET IDENTITY_INSERT dim_Gender OFF;
GO

SET IDENTITY_INSERT dim_InternetServiceType ON;
SET IDENTITY_INSERT dim_InternetServiceType OFF;
GO

SET IDENTITY_INSERT dim_ContractType ON;
SET IDENTITY_INSERT dim_ContractType OFF;
GO

SET IDENTITY_INSERT dim_PaymentMethod ON;
SET IDENTITY_INSERT dim_PaymentMethod OFF;
GO

